// Record when this answer arrived, together with the query it belongs to.
const q = $('Loop Over Items').item.json;
const out = typeof $json.output === 'string' ? $json.output.trim() : '';
return { json: { id: q.id, lang: q.lang, query: q.query, answer: out || 'ERROR: no answer returned', started_at: q.started_at, at: Date.now() } };

// Sort by query ID and estimate each response time from consecutive timestamps.
const rows = $input.all().map((i) => i.json).sort((a, b) => a.at - b.at);
let prev = rows.length ? rows[0].started_at : 0;
const out = rows.map((r) => { const secs = Math.round((r.at - prev) / 100) / 10; prev = r.at; return { ...r, secs }; });
out.sort((a, b) => a.id - b.id);
return out.map((r) => ({ json: { 'ID': r.id, 'Lang': r.lang, 'Test query': r.query, 'Answer': r.answer, 'Response time (s)': r.secs } }));
